package com.example.dateorganizer;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.provider.*;import android.database.*;import android.widget.*;import android.media.ExifInterface;import java.util.*;import java.io.*;import java.text.*;import java.security.*;
public class MainActivity extends Activity {
 Uri src,dst; TextView status; Button move; volatile boolean stop=false; ArrayList<Item> items=new ArrayList<>();
 static class Item {Uri uri;String name,date,mime;Item(Uri u,String n,String d,String m){uri=u;name=n;date=d;mime=m;}}
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(20,30,20,20);TextView t=new TextView(this);t.setText("날짜별 파일 자동정리");t.setTextSize(23);l.addView(t);
 add(l,"1. 원본 폴더 선택",()->pick(1));add(l,"2. 대상 폴더 선택",()->pick(2));add(l,"3. 검색 및 미리보기",()->scan());
 move=add(l,"4. 날짜-특징 폴더로 이동",()->new AlertDialog.Builder(this).setTitle("파일 이동 승인").setMessage(items.size()+"개 파일을 검증 후 이동합니다. 진행할까요?").setNegativeButton("취소",null).setPositiveButton("이동",(d,w)->process()).show());move.setEnabled(false);
 add(l,"작업 중지",()->stop=true);status=new TextView(this);status.setText("폴더를 선택하세요. 사진과 문서는 외부로 전송하지 않습니다.");l.addView(status);setContentView(l);}
 Button add(LinearLayout l,String s,Runnable a){Button b=new Button(this);b.setText(s);l.addView(b);b.setOnClickListener(v->a.run());return b;}
 void pick(int code){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,code);}
 protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(c!=RESULT_OK||data==null)return;Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(Exception ignored){}if(r==1)src=u;else dst=u;show("원본 "+(src!=null?"선택됨":"미선택")+" / 대상 "+(dst!=null?"선택됨":"미선택"));}
 Uri root(Uri u){return DocumentsContract.buildDocumentUriUsingTree(u,DocumentsContract.getTreeDocumentId(u));}
 String id(Uri u){return DocumentsContract.getDocumentId(u);}
 void show(String s){runOnUiThread(()->status.setText(s));}
 boolean photo(String n){return n.matches("(?i).*\\.(jpg|jpeg|png|heic|webp|gif)$");}
 boolean video(String n){return n.matches("(?i).*\\.(mp4|mov|avi|mkv)$");}
 boolean supported(String n){return photo(n)||video(n)||n.matches("(?i).*\\.(pdf|hwp|hwpx|doc|docx|xls|xlsx|ppt|pptx|txt|csv)$");}
 String category(String n){n=n.toLowerCase(Locale.ROOT);if(n.matches(".*(beach|sea|ocean|바다|해변).*"))return "바다";if(n.matches(".*(food|meal|음식|식사).*"))return "음식";if(n.matches(".*(travel|trip|여행).*"))return "여행";if(n.matches(".*(family|가족).*"))return "가족";if(n.matches(".*(scan|receipt|문서|영수증).*"))return "문서촬영";return "기타사진";}
 String folder(Item i){String d=i.date.matches("\\d{4}/\\d{2}/\\d{2}")?i.date.substring(2).replace("/",""):"날짜미상";return d+"-"+(photo(i.name)?category(i.name):video(i.name)?"동영상":"문서");}
 void scan(){if(src==null||dst==null){show("두 폴더를 선택하세요.");return;}if(src.equals(dst)){show("원본과 대상은 달라야 합니다.");return;}stop=false;items.clear();move.setEnabled(false);show("검색 중...");new Thread(()->{walk(root(src),0);StringBuilder b=new StringBuilder("검색 "+items.size()+"개\\n");for(int j=0;j<Math.min(items.size(),15);j++){Item i=items.get(j);b.append(folder(i)).append(" / ").append(i.name).append("\\n");}show(b.toString());runOnUiThread(()->move.setEnabled(!items.isEmpty()));}).start();}
 void walk(Uri parent,int depth){if(stop||depth>30)return;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(src,id(parent));try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_LAST_MODIFIED},null,null,null)){if(c==null)return;while(c.moveToNext()&&!stop){String name=c.getString(1),mime=c.getString(2);if(name==null)continue;Uri u=DocumentsContract.buildDocumentUriUsingTree(src,c.getString(0));if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){walk(u,depth+1);continue;}if(!supported(name))continue;long ms=c.isNull(3)?0:c.getLong(3);String date=ms>0?new SimpleDateFormat("yyyy/MM/dd",Locale.KOREA).format(new Date(ms)):"날짜미상";if(photo(name))try(InputStream in=getContentResolver().openInputStream(u)){if(in!=null){String ex=new ExifInterface(in).getAttribute(ExifInterface.TAG_DATETIME_ORIGINAL);if(ex!=null&&ex.matches("\\d{4}:\\d{2}:\\d{2}.*"))date=ex.substring(0,10).replace(':','/');}}catch(Exception ignored){}items.add(new Item(u,name,date,mime));}}catch(Exception ex){show("검색 오류: "+ex.getMessage());}}
 Uri ensure(Uri parent,String name)throws Exception{Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(dst,id(parent));try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(c!=null)while(c.moveToNext())if(name.equals(c.getString(1))&&DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2)))return DocumentsContract.buildDocumentUriUsingTree(dst,c.getString(0));}Uri u=DocumentsContract.createDocument(getContentResolver(),parent,DocumentsContract.Document.MIME_TYPE_DIR,name);if(u==null)throw new IOException("폴더 생성 실패");return u;}
 boolean exists(Uri parent,String name){Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(dst,id(parent));try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c!=null)while(c.moveToNext())if(name.equals(c.getString(0)))return true;}return false;}
 byte[] hash(Uri u)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=getContentResolver().openInputStream(u)){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)md.update(buf,0,n);}return md.digest();}
 void process(){stop=false;move.setEnabled(false);new Thread(()->{int done=0,failed=0;for(Item i:items){if(stop)break;Uri target=null;try{Uri dir=ensure(root(dst),folder(i));String base=i.name.replace("/","_"),name=base;int k=1;while(exists(dir,name)){int p=base.lastIndexOf('.');name=(p<0?base:base.substring(0,p))+"_"+k+++(p<0?"":base.substring(p));}target=DocumentsContract.createDocument(getContentResolver(),dir,i.mime==null?"application/octet-stream":i.mime,name);if(target==null)throw new IOException("대상 파일 생성 실패");try(InputStream in=getContentResolver().openInputStream(i.uri);OutputStream out=getContentResolver().openOutputStream(target)){byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1){if(stop)throw new IOException("작업 중지");out.write(buf,0,n);}out.flush();}if(!Arrays.equals(hash(i.uri),hash(target)))throw new IOException("파일 검증 실패");if(!DocumentsContract.deleteDocument(getContentResolver(),i.uri))throw new IOException("복사는 완료되었으나 원본 삭제 실패");done++;}catch(Exception ex){failed++;if(target!=null&& !("복사는 완료되었으나 원본 삭제 실패".equals(ex.getMessage())))try{DocumentsContract.deleteDocument(getContentResolver(),target);}catch(Exception ignored){}}show("완료 "+done+" / 실패 "+failed+" / 전체 "+items.size());}show("작업 종료: 이동 "+done+"개, 실패 "+failed+"개");}).start();}
}